const D = { scale:1, energy:.62, density:.55, speed:1, vapor:.58, branch:.5, hue:210, x:.5, y:.5, style:'ice', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clamp = (v,a,b)=> v<a?a:(v>b?b:v);
const SQ3 = 0.8660254;               // sqrt(3)/2
const intn = (K.intensity!=null?K.intensity:.6);
const styles = ['ice','gold-frost','spectral','neon','ink'];
let stMode = styles.indexOf(P.style); if (stMode<0) stMode=0;

// ---- hex grid geometry (fixed) ----
const N = 91, R = 45, Rlimit = 42;   // hex grid: N cells wide, center at (R,R), growth cap at Rlimit

// ---- coarse buffer sized to canvas AR, <=256, ~200 short side ----
const AR = width/Math.max(1,height);
let BW, BH;
if (AR>=1){ BH = 200; BW = Math.min(256, Math.round(BH*AR)); }
else { BW = 200; BH = Math.min(256, Math.round(BW/AR)); }
const minB = Math.min(BW,BH);
if (!S.g || S.bw!==BW || S.bh!==BH){ if(S.g) S.g.remove(); S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bw=BW; S.bh=BH; S.lutKey=''; }

// ---- per-seed hash ----
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7 + 17.3) * 43758.5453; return s - Math.floor(s); };

// ---- geometry caches (angle, hex-dist, euclid-radius) — depend only on N ----
if (!S.ANG || S.geoN!==N){
  S.geoN = N;
  S.ANG = new Float32Array(N*N); S.HD = new Float32Array(N*N); S.RN = new Float32Array(N*N);
  for (let r=0;r<N;r++){ const dr=r-R; for (let q=0;q<N;q++){ const dq=q-R; const i=q+r*N;
    const ux = dq + dr*0.5, uy = dr*SQ3;
    S.ANG[i] = Math.atan2(uy,ux);
    S.HD[i]  = (Math.abs(dq)+Math.abs(dr)+Math.abs(dq+dr))*0.5;
    S.RN[i]  = Math.sqrt(ux*ux+uy*uy);
  }}
}
const ANG=S.ANG, HD=S.HD, RN=S.RN;

// ---- Reiter constants (live-pokeable + per-seed offset) ----
const gammaEff = (0.0009 + P.branch*0.0062) * (0.7 + fr(2)*0.7);
const alphaEff = clamp(1.0 * (0.9 + fr(3)*0.25), 0.6, 1.35);

// ---- dramaturgy: epoch regrow with soft melt ----
const period = 38;
const epoch = Math.floor(K.t/period);
const tp = (K.t - epoch*period)/period;            // 0..1 within this flake's life
const meltStart = 0.82;
const globalA = tp<meltStart ? 1 : clamp(1-(tp-meltStart)/(1-meltStart),0,1);

const simKey = N+'|'+P.seed+'|'+epoch;
if (S.simKey !== simKey){
  S.simKey = simKey;
  const betaEff = clamp(P.vapor + (fr(1)-0.5)*0.10, 0.30, 0.95);
  S.s  = new Float32Array(N*N); S.s.fill(betaEff);
  S.s2 = new Float32Array(N*N);
  S.u  = new Float32Array(N*N); S.u.fill(betaEff);
  S.rc = new Uint8Array(N*N);
  S.fr = new Uint8Array(N*N);
  // seed a small hex core (HD<=2) so growth starts visible & symmetric
  for (let i=0;i<N*N;i++){ if (HD[i]<=2){ S.fr[i]=1; S.s[i]=1.0; } }
  S.done=false; S.reached=false;
  // glint sample points (6-fold-ish scatter across the disc)
  const NG=64; S.gq=new Int32Array(NG); S.gr=new Int32Array(NG);
  S.gph=new Float32Array(NG); S.grate=new Float32Array(NG);
  for (let k=0;k<NG;k++){ const a=fr(k*3+11)*6.2832, rad=(0.22+0.72*fr(k*3+12))*Rlimit;
    const dr=Math.round(Math.sin(a)*rad/SQ3), dq=Math.round(Math.cos(a)*rad - dr*0.5);
    S.gq[k]=dq+R; S.gr[k]=dr+R; S.gph[k]=fr(k*3+13)*6.2832; S.grate[k]=1.4+fr(k*3+14)*3.6; }
}
const FR=S.fr;

// ---- Reiter CA step ---- (reads S.s/S.s2 fresh each call so multi-step-per-frame swaps correctly)
function stepCA(){
  const s=S.s, s2=S.s2, u=S.u, rc=S.rc;
  const a2 = alphaEff*0.5;
  s2.set(s);
  // pass A: receptive flag + non-receptive vapor u
  for (let r=1;r<N-1;r++){ const b=r*N;
    for (let q=1;q<N-1;q++){ const i=b+q;
      const rec = FR[i]||FR[i+1]||FR[i-1]||FR[i+N]||FR[i-N]||FR[i+1-N]||FR[i-1+N];
      rc[i]=rec?1:0; u[i]=rec?0:s[i];
    }}
  // pass B: diffuse u, add gamma to receptive, freeze on s>=1
  for (let r=1;r<N-1;r++){ const b=r*N;
    for (let q=1;q<N-1;q++){ const i=b+q;
      const un=u[i];
      const mean=(u[i+1]+u[i-1]+u[i+N]+u[i-N]+u[i+1-N]+u[i-1+N])*0.16666667;
      const du=un + a2*(mean-un);
      const v = rc[i] ? (s[i]+gammaEff) : 0;
      let ns=v+du; if(ns>3.5) ns=3.5;
      s2[i]=ns;
      if(!FR[i] && ns>=1 && HD[i]<=Rlimit){ FR[i]=1; if(HD[i]>=Rlimit-2) S.reached=true; }
    }}
  S.s=s2; S.s2=s;                    // swap
}
const melting = tp>=meltStart;
let G = (S.done||melting) ? 0 : Math.round((2 + P.speed*2.4)*(0.45+P.density*0.85) + intn*1.5 + A.bass*4);
G = clamp(G,0,12);
for (let g=0; g<G; g++){ stepCA(); }
if (S.reached) S.done=true;
const sFld = S.s;                    // current field after swap(s)

// ---- neon needs an edge map ----
if (stMode===3){
  const ed = S.edge || (S.edge=new Uint8Array(N*N)); ed.fill(0);
  for (let r=1;r<N-1;r++){ const b=r*N; for (let q=1;q<N-1;q++){ const i=b+q;
    if (FR[i] && (!FR[i+1]||!FR[i-1]||!FR[i+N]||!FR[i-N]||!FR[i+1-N]||!FR[i-1+N])) ed[i]=1; }}
}
const EDG = S.edge;

// ---- pixel<->cell LUT + halo (depends on size, anchor, scale) ----
const cellPix = 0.82*minB*clamp(P.scale,0.4,1.9)/N;
const cx = P.x*BW, cy = P.y*BH;
const lutKey = BW+'x'+BH+'|'+P.x.toFixed(3)+'|'+P.y.toFixed(3)+'|'+P.scale.toFixed(3);
if (S.lutKey !== lutKey){
  S.lutKey = lutKey;
  S.lut = new Int32Array(BW*BH); S.halo = new Float32Array(BW*BH);
  const inv = 1/cellPix, invY = 1/(cellPix*SQ3), hR = 0.62*minB;
  for (let j=0;j<BH;j++){ for (let i=0;i<BW;i++){ const pi=j*BW+i;
    const X=(i-cx)*inv, Y=(j-cy);
    const frF = Y*invY;                       // fractional dr
    const fqF = X - frF*0.5;                   // fractional dq
    // cube round
    let rx=fqF, rz=frF, ry=-rx-rz;
    let RX=Math.round(rx), RY=Math.round(ry), RZ=Math.round(rz);
    const xd=Math.abs(RX-rx), yd=Math.abs(RY-ry), zd=Math.abs(RZ-rz);
    if (xd>yd && xd>zd) RX=-RY-RZ; else if (yd>zd) RY=-RX-RZ; else RZ=-RX-RY;
    const q=RX+R, r=RZ+R;
    S.lut[pi] = (q>=0&&q<N&&r>=0&&r<N) ? (q+r*N) : -1;
    const pr=Math.sqrt((i-cx)*(i-cx)+(j-cy)*(j-cy));
    S.halo[pi] = clamp(1-pr/hR,0,1);
  }}
}
const LUT=S.lut, HALO=S.halo;

// ---- style constants ----
// ground: [hue, sat, base-B, halo-amt, vapor-amt]
const G0=[[232,76,21,24,11],[26,70,16,18,9],[252,58,15,20,9],[235,80,11,13,8],[228,16,10,12,7]][stMode];
// precompute unit ground rgb (B=100)
function hsb(h,sa,b,out){ sa/=100; b/=100; h=((h%360)+360)%360; const c=b*sa, x=c*(1-Math.abs((h/60)%2-1)), m=b-c;
  let r,g,bl; if(h<60){r=c;g=x;bl=0;}else if(h<120){r=x;g=c;bl=0;}else if(h<180){r=0;g=c;bl=x;}
