const RGBt=[0,0,0];
const energy=P.energy;
const shim = (5+energy*15)*(0.55+intn*0.6) + A.treble*18 + A.rms*9;
const shTime = K.t*(0.5+P.speed*0.9);
const facetFreq = 5 + P.density*9;
const exposure = 0.72 + energy*0.55 + intn*0.28 + A.rms*0.5;
const hbShift = Math.sin(K.t*0.05)*7 + (K.section||0)*6;

// ---- render into buffer ----
const g2=S.g; g2.loadPixels(); const px=g2.pixels;
for (let pi=0; pi<BW*BH; pi++){
  const cell = LUT[pi];
  const halo = HALO[pi];
  const vv = cell>=0 ? sFld[cell] : G0? P.vapor : 0;
  const groundB = G0[2] + halo*G0[3] + clamp(vv,0,1)*G0[4];
