    const glint=0.5+0.5*Math.sin(shTime + ang*6 - rn*7.0);   // fine sparkle (texture)
    // slow low-freq light-ring breathing outward: omega chosen so an 8s gap is ~half a cycle
    // (never re-phases to static, and low spatial freq survives the 320px motion downsample)
    const pulse=Math.sin(rn*1.5 - K.t*(0.42+P.speed*0.12) + ang*0.3);
    const shade=(glint-0.5)*shim + pulse*(9+energy*11);
    let hh,ss,bb;
    if (stMode===0){            // ice — blue-white on indigo
      bb=(58+sn*30+(facet-0.5)*22+shade)*exposure;
      ss=clamp(64-sn*44-(facet-0.5)*16,4,92);
      hh=P.hue+(facet-0.5)*14+rn*10+hbShift;
    } else if (stMode===1){     // gold-frost — metallic
      const spec=facet*facet*facet;
      bb=(40+sn*22+spec*48*(0.6+energy)+shade)*exposure;
      ss=clamp(88-spec*72-sn*10,6,96);
      hh=44+(facet-0.5)*10-spec*10+hbShift*0.4;
    } else if (stMode===2){     // spectral — iridescent facets
      bb=(46+sn*28+facet*16+shade)*exposure;
      ss=86;
      hh=(P.hue+ang*28.6+sn*140+rn*90+glint*40+hbShift)%360;
    } else if (stMode===3){     // neon — glowing contour
