        ss=72; hh=185+(0.5+0.5*Math.sin(ang*3+rn*4))*80+hbShift;
      } else {
        bb=(15+sn*11+halo*4+pulse*7)*exposure; ss=64; hh=232+hbShift*0.3;
      }
    } else {                    // ink — white flake on black
      bb=(46+sn*46+(facet-0.5)*20+shade)*exposure;
      ss=clamp(8-(facet-0.5)*4,0,20); hh=220;
    }
    hsb(hh,ss,clamp(bb,0,100),RGBt);
    r8=RGBt[0]; g8=RGBt[1]; b8=RGBt[2];
    if (globalA<1){ const gb=groundB/100; const gr=gU[0]*gb, gg=gU[1]*gb, gbl=gU[2]*gb;
      r8=gr+(r8-gr)*globalA; g8=gg+(g8-gg)*globalA; b8=gbl+(b8-gbl)*globalA; }
  } else {
    const gb=groundB/100; r8=gU[0]*gb; g8=gU[1]*gb; b8=gU[2]*gb;
  }
  const o=4*pi;
  px[o]  = r8<0?0:(r8>255?255:r8);
  px[o+1]= g8<0?0:(g8>255?255:g8);
  px[o+2]= b8<0?0:(b8>255?255:b8);
