const minC=Math.min(width,height);
const rot = (fr(7)>0.5?1:-1) * K.t * 0.030;
const ax=P.x*width, ay=P.y*height;
push();
translate(ax,ay); rotate(rot); translate(-ax,-ay);
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g2,0,0,width,height);
noTint();
// glitter twinkles ride the same transform so they sit on the crystal tips
blendMode(ADD); noStroke();
const NG = Math.round(24 + P.density*40);
for (let k=0;k<NG;k++){
  const gq=S.gq[k], gr=S.gr[k]; const ci=gq+gr*N;
  if (!(ci>=0 && ci<N*N && FR[ci])) continue;
  const dq=gq-R, dr=gr-R;
  const gx=(cx+(dq+dr*0.5)*cellPix)/BW*width;
  const gy=(cy+dr*SQ3*cellPix)/BH*height;
  const tw=Math.pow(0.5+0.5*Math.sin(K.t*S.grate[k]+S.gph[k]),4);
  const gb=((28+tw*66)*(0.4+energy*0.8) + A.treble*40)*globalA*0.5;
  const gh = stMode===2 ? (P.hue+dq*4+dr*4)%360 : (stMode===1?46:(stMode===3?190:P.hue+8));
  const gsat = stMode===4?10:(stMode===1?40:34);
  fill(((gh%360)+360)%360, gsat, 100, clamp(gb,0,58));
  circle(gx, gy, (1.4+tw*3.2)*(minC*0.006));
}
blendMode(BLEND);
pop();
